public static long pathCount(boolean[][] blocked) {
    int rows=blocked.length, cols=blocked[0].length;
    long[][] ways=new long[rows][cols];
    for (int r=0; r<rows; r++) {
        for (int c=0; c<cols; c++) {
            if (blocked[r][c]) ways[r][c]=0;
            else if (r==0 && c==0) ways[r][c]=1;
            else {
                long above=r>0 ? ways[r-1][c] : 0;
                long left=c>0 ? ways[r][c-1] : 0;
                ways[r][c]=above+left;
            }
        }
    }
    return ways[rows-1][cols-1];
}

