```java
public static long coveredLength(int[][] intervals) {
    if (intervals.length == 0) return 0L;
    int[][] copy = new int[intervals.length][2];
    for (int i=0; i<intervals.length; i++) copy[i]=intervals[i].clone();
    java.util.Arrays.sort(copy, (a,b)->Integer.compare(a[0],b[0]));
    int left=copy[0][0], right=copy[0][1];
    long length=0;
    for (int i=1; i<copy.length; i++) {
        if (copy[i][0]<=right) right=Math.max(right,copy[i][1]);
        else {
            length+=(long)right-left;
            left=copy[i][0]; right=copy[i][1];
        }
    }
    length+=(long)right-left;
    return length;
}
```

