public static String[] distinctTags(String[] tags) {
    java.util.HashSet<String> seen=new java.util.HashSet<>();
    java.util.ArrayList<String> retained=new java.util.ArrayList<>();
    for (String tag:tags) {
        String key=tag.toLowerCase(java.util.Locale.ROOT);
        if (seen.add(key)) retained.add(tag);
    }
    return retained.toArray(new String[0]);
}
```

