```java
public static long base36Value(String token) {
    if (token.isEmpty()) return -1L;
    long value=0L;
    for (int i=0; i<token.length(); i++) {
        char c=token.charAt(i);
        int digit;
        if (c>='0' && c<='9') digit=c-'0';
        else if (c>='a' && c<='z') digit=c-'a'+10;
        else if (c>='A' && c<='Z') digit=c-'A'+10;
        else return -1L;
        value=value*36+digit;
    }
    return value;
}
```

